  ('lake-placid-whiteface-new-york', '12A', 'Lake Placid / Whiteface', 'United States', 'The only US town to host the Winter Olympics', 'live', 'verified', 'northernLights', 'Mid-Atlantic', '{"ski","entertainment","ultra","family","romance","culinary"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Lake Placid = the only US town to host the Winter Olympics twice — 1932 (III, first in North America) + 1980 (XIII, ''Miracle on Ice''); see olympic_training_venue for full working-venue detail","Whiteface (Wilmington, ~13 mi) = the 1980 Olympic alpine venue, ORDA-operated; greatest continuous vertical in the East ~3,430 ft (incl. hike-to Slides), lift-served ~3,166 ft (top unload ~4,386 ft / base ~1,220 ft); ~94 trails, ~299 acres, 12 lifts, ~99% snowmaking","USOPC Lake Placid Olympic & Paralympic Training Center opened 1982; ORDA ~$500M state revitalization ahead of the Jan 2023 FISU World University Games","PASSES: Whiteface is NOT on Ikon — on ORDA''s SKI3 pass (with Gore + Belleayre) + Mountain Collective 2025/26 (up to 2 days)","Luxury lodging: Lake Placid Lodge (Relais & Chateaux), The Whiteface Lodge, Mirror Lake Inn Resort & Spa; village on Mirror Lake; access via the Northway (I-87)","Adirondack Medical Center — Saranac Lake (Adirondack Health) nearest hospital (~20-25 min)"],"safety":{"emergency":"911 (nationwide); backcountry/High Peaks rescue via NYS DEC Forest Rangers / 911","hospital":"Adirondack Medical Center — Saranac Lake (Adirondack Health, 24/7 ER, ~20-25 min); serious cases to Burlington VT / Albany trauma centers","malaria":"none","yellow_fever":"not required","activity_note":"EXTREME COLD + WIND-CHILL (Whiteface notoriously cold/windy — upper-mountain wind-holds, frostbite fast); ICE/HARDPACK + FREEZE-THAW (defining Eastern condition — boilerplate/blue ice/loss-of-edge; The Slides hike-to expert-only); Northeast winter driving (I-87 + Wilmington roads; black ice/nor''easters; 511NY); avalanche LOW in-bounds (shallow snowpack, no daily forecast) but not none in backcountry; tree wells de-emphasized; Olympic-venue activity safety (bobsled/coaster/jumps/skating — follow ORDA staff + limits)"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) ski + winter venues + weekend peaks (NYC/Montreal/Boston drive market); summer Jul-Aug (lake, High Peaks, venue tours)","shoulder":"early season (mid-late Dec), Jan weekdays, March spring skiing, fall foliage (late Sep-mid Oct)","green":"Apr-May + Nov-early Dec (between-season lulls / mud season — verify)","booking_lead":"Christmas/NY + top lodges 6-12 mo; Presidents''/Feb 3-6 mo; summer lake + foliage 3-6 mo; shoulder/midweek 1-8 wk (weekend drive-in Northeast/Montreal ski market)","off_season_specials":"March spring-ski deals; summer lake + High Peaks + Olympic-venue-tour layer (Jun-Oct); fall foliage; Olympic-heritage day-visits year-round","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, fall foliage (late Sep-mid Oct), ORDA winter-sport competitions (verify 2027), summer lake holidays (Jul 4)","campaign_start":"FIRE ski mid-late Mar (ahead of Apr-Jun early-bird) + late Aug-early Sep (ahead of Sep-Nov fall wave); market summer lake/Olympic-venue/foliage by Jan-Feb"},"jewels":[{"name":"Ski the biggest vertical in the East — Whiteface","si_tag":"Winter / Ski","status":"future","tier":"comfort","price_band":"~USD 95-189/day lift","timing":"ski ~late Dec-Mar, snow + wind-dependent","draw_rank":1,"hook":"the greatest continuous vertical drop in eastern North America, ~3,430 ft; ~94 trails over ~299 acres, 12 lifts, ~99% snowmaking","si":"Winter / Ski","blurb":"the greatest continuous vertical drop in eastern North America, ~3,430 ft; ~94 trails over ~299 acres, 12 lifts, ~99% snowmaking","when":"ski ~late Dec-Mar, snow + wind-dependent","commission":"DMC/ski-op 10-20% (embedded-capable)"},{"name":"Hike The Slides on the right day","si_tag":"Winter / Ski","status":"future","tie